// rated for political noteworthiness and truthfulness on independent 1-5 scales.
// Sources that could not be fully read are listed in PENDING_SOURCES.md, not here.
// Record ids keep the legacy "kf-" prefix (kf-<paperId>-<n>) for id stability.
//
// Two fields of the skill's schema are not stored here. The verbatim surrounding paragraph (`context`) lives in
// data/fact-bank-context.js as FACT_CONTEXT["<record id>"], because a collapsed card never shows it and it was a
// quarter of this file: the Fact Bank loads that file the first time a card is opened. The plain-English
// restatement (`factPlain`) was dropped: no view shows it.

